import { registerWebComponents } from '@domg-wc/common';
import { VlTextareaComponent } from '@domg-wc/components/form';

registerWebComponents([VlTextareaComponent]);

// vl-change volgt op elke wijziging van de waarde, ook door code; vl-input enkel op invoer door de gebruiker.
// event.detail.value is de nieuwe tekst.
document.querySelector('vl-textarea').addEventListener('vl-input', (event) => {
    console.log(event.detail.value);
});
